package org.simpleweather.app;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Each child dialog retains its parent; selections apply without closing the page. */
final class SettingsScreen {
    private final MainActivity a;
    private final SharedPreferences prefs;
    private static final String[] COLOR_NAMES={"黑色","蓝色","绿色","红色","紫色","白色"};
    private static final int[] COLORS={Color.BLACK,0xFF246BCE,0xFF287C60,0xFFB83636,0xFF7852A8,Color.WHITE};
    private static final long[] INTERVALS={1000,5000,10000,30000,60000,180000,300000,600000};
    private static final String[] INTERVAL_NAMES={"1秒","5秒","10秒","30秒","1分钟","3分钟","5分钟","10分钟"};
    SettingsScreen(MainActivity a){this.a=a;prefs=a.preferences;}
    private LinearLayout form(){LinearLayout c=a.column();c.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(16));return c;}
    private ScrollView scroll(LinearLayout c){ScrollView s=new ScrollView(a);s.addView(c);return s;}
    private AlertDialog dialog(String title,LinearLayout c){return new ToolDialog(a).setTitle(title).setView(scroll(c)).setNegativeButton("返回",null).show();}
    private TextView action(LinearLayout c,String label,Runnable click){TextView b=a.button(label,false,click);c.addView(b);a.gap(c,10);return b;}
    void show(){LinearLayout c=form();String[] names={"背景","描边","天气","课程表","定位","天气地图","底部栏目","关于"};Runnable[] actions={this::background,this::outline,this::weather,a::scheduleSettings,this::location,this::maps,()->order(false),this::about};for(int n=0;n<names.length;n++)action(c,names[n],actions[n]);AlertDialog root=new ToolDialog(a).setTitle("设置").setView(scroll(c)).setNeutralButton("一键恢复默认设置",null).setNegativeButton("关闭",null).create();root.setOnShowListener(v->root.getButton(-3).setOnClickListener(b->new ToolDialog(a).setTitle("恢复默认设置？").setMessage("恢复背景、描边、栏目、定位、课表前缀、学期及上课时间等设置。课程、收藏地区和天气缓存会保留。若课程使用超出默认范围的周次或节次，将保留这些必要范围及额外节次时间，以免课程失效。").setPositiveButton("恢复默认",(d,n)->{a.restoreDefaults();root.dismiss();show();a.toast("已恢复默认设置");}).setNegativeButton("取消",null).show()));root.show();}
    private void background(){LinearLayout c=form();action(c,"从手机导入并调整背景",a::selectBackground);action(c,"恢复默认背景",a::resetBackground);c.addView(a.text("背景亮度",14,a.INK,true));c.addView(a.text("向右调整让背景图片更明显。",13,a.MUTED,false));SeekBar brightness=new SeekBar(a);brightness.setContentDescription("背景亮度");brightness.setMax(100);brightness.setProgress(prefs.getInt("background_brightness",20));brightness.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){if(user)prefs.edit().putInt("background_brightness",n).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){a.refreshScreen();}});c.addView(brightness,a.lp(-1,48));dialog("背景",c);}
    private String colorLabel(){int color=a.outlineColor();for(int n=0;n<COLORS.length;n++)if(color==COLORS[n])return "设置描边颜色 · 当前"+COLOR_NAMES[n];return String.format(Locale.ROOT,"设置描边颜色 · 当前自定义色 #%06X",color&0xffffff);}
    private void outline(){LinearLayout c=form();Switch toggle=new Switch(a);toggle.setText("显示区域与按钮描边");toggle.setTextSize(15);toggle.setChecked(prefs.getBoolean("outline",true));toggle.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean("outline",on).apply();a.refreshScreen();});c.addView(toggle,a.lp(-1,54));a.gap(c,10);TextView color=action(c,colorLabel(),()->{});color.setOnClickListener(v->colors(()->color.setText(colorLabel())));c.addView(a.text("支持预设颜色及 #RRGGBB 自定义颜色。",13,a.MUTED,false));dialog("描边",c);}
    private void colors(Runnable changed){String[] labels=Arrays.copyOf(COLOR_NAMES,COLOR_NAMES.length+1);labels[labels.length-1]="自定义十六进制颜色";int current=COLORS.length;for(int n=0;n<COLORS.length;n++)if(a.outlineColor()==COLORS[n])current=n;AlertDialog d=new ToolDialog(a).setTitle("描边颜色").setSingleChoiceItems(labels,current,(x,n)->{if(n<COLORS.length){prefs.edit().putInt("outline_color",COLORS[n]).apply();a.refreshScreen();changed.run();}else customColor(()->{changed.run();((AlertDialog)x).getListView().setItemChecked(COLORS.length,true);});}).setNegativeButton("返回",null).show();d.setOnDismissListener(v->changed.run());}
    private void customColor(Runnable changed){EditText input=new EditText(a);input.setSingleLine(true);input.setHint("#000000");input.setText(String.format(Locale.ROOT,"#%06X",a.outlineColor()&0xffffff));input.setSelectAllOnFocus(true);AlertDialog d=new ToolDialog(a).setTitle("输入 #RRGGBB 颜色").setView(input).setPositiveButton("保存",null).setNegativeButton("返回",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{String s=input.getText().toString().trim();if(!s.matches("#[0-9a-fA-F]{6}")){a.toast("请输入 # 加六位十六进制颜色");return;}prefs.edit().putInt("outline_color",Color.parseColor(s)).apply();a.refreshScreen();changed.run();a.toast("描边颜色已保存");}));d.show();}
    void weather(){LinearLayout c=form();action(c,"栏目显示与排序",()->order(true));action(c,"查看图例",this::legend);dialog("天气设置",c);}
    private void legend(){LinearLayout c=form();int[] codes={0,1,2,3,45,48,51,53,55,56,57,61,63,65,66,67,71,73,75,77,80,81,82,85,86,95,96,99,-1};c.addView(a.text("左为白天，右为夜间；图标对应 WMO 天气代码。",13,a.MUTED,false));for(int code:codes){LinearLayout r=a.row();r.addView(new WeatherIcon(a,code,true),a.lp(50,50));r.addView(new WeatherIcon(a,code,false),a.lp(50,50));r.addView(a.text(WeatherData.condition(code)+(code>=0?" · "+code:""),14,a.INK,false),new LinearLayout.LayoutParams(0,-2,1));c.addView(r);a.gap(c,6);}dialog("天气图例",c);}
    void location(){LinearLayout c=form();action(c,"定位方式",this::locationProvider);action(c,"自动定位时间间隔",this::locationInterval);c.addView(a.text("时间间隔为向系统请求更新的最短间隔；系统可能延迟或复用定位结果。页面每秒显示真实定位结果的时间，不会把请求当作新结果。",13,a.MUTED,false));dialog("定位设置",c);}
    private void locationProvider(){String[] names={"GPS 硬件定位","网络定位（系统提供）"};int current=prefs.getString("location_provider","gps").equals("network")?1:0;new ToolDialog(a).setTitle("定位方式").setSingleChoiceItems(names,current,(d,n)->{prefs.edit().putString("location_provider",n==0?"gps":"network").apply();a.locationModeChanged();}).setNegativeButton("返回",null).show();}
    private void locationInterval(){long interval=prefs.getLong("location_interval",1000);int current=0;for(int n=0;n<INTERVALS.length;n++)if(interval==INTERVALS[n])current=n;new ToolDialog(a).setTitle("自动定位时间间隔").setSingleChoiceItems(INTERVAL_NAMES,current,(d,n)->{prefs.edit().putLong("location_interval",INTERVALS[n]).apply();a.locationIntervalChanged();}).setNegativeButton("返回",null).show();}
    void maps(){String[] names={"全国","华北","东北","华东","华中","华南","西南","西北"};int selected=Math.max(0,Math.min(7,prefs.getInt("radar_region",0)));new ToolDialog(a).setTitle("天气地图 · 默认雷达").setSingleChoiceItems(names,selected,(d,n)->{prefs.edit().putInt("radar_region",n).apply();a.refreshScreen();}).setNegativeButton("返回",null).show();}
    private void about(){LinearLayout c=form();action(c,"版本更新记录",a::updates);action(c,"数据来源与隐私",a::about);c.addView(a.text("呆呆工具箱 1.0.2",14,a.MUTED,false));dialog("关于",c);}
    private void order(boolean weather){
        String[] labels=weather?MainActivity.WEATHER_NAMES:MainActivity.TAB_NAMES;String key=weather?"weather":"tab";List<Integer> ids=DisplayOrder.parse(prefs.getString(key+"_order",""),labels.length);LinearLayout c=form();c.addView(a.text(weather?"勾选显示，使用箭头调整上下顺序。来源署名跟随天气内容保留。":"至少保留一个栏目；一个栏目时隐藏底栏，五个栏目时使用左右箭头翻页。",13,a.MUTED,false));a.gap(c,12);LinearLayout list=a.column();c.addView(list);Runnable[] render=new Runnable[1];render[0]=()->{list.removeAllViews();for(int pos=0;pos<ids.size();pos++){final int index=pos,id=ids.get(pos);LinearLayout r=a.row();CheckBox check=new CheckBox(a);check.setText(labels[id]);check.setTextSize(14);check.setChecked(prefs.getBoolean(key+"_show_"+id,weather||id<3));check.setOnCheckedChangeListener((v,on)->{if(!weather&&!on&&a.visibleTabs().size()<=1){check.setChecked(true);a.toast("至少保留一个底部栏目");return;}prefs.edit().putBoolean(key+"_show_"+id,on).apply();a.refreshScreen();});r.addView(check,new LinearLayout.LayoutParams(0,-2,1));TextView up=a.button("↑",false,()->{if(index>0){Collections.swap(ids,index,index-1);prefs.edit().putString(key+"_order",DisplayOrder.encode(ids)).apply();a.refreshScreen();render[0].run();}});up.setContentDescription(labels[id]+"上移");up.setPadding(0,0,0,0);r.addView(up,a.lp(42,48));TextView down=a.button("↓",false,()->{if(index+1<ids.size()){Collections.swap(ids,index,index+1);prefs.edit().putString(key+"_order",DisplayOrder.encode(ids)).apply();a.refreshScreen();render[0].run();}});down.setContentDescription(labels[id]+"下移");down.setPadding(0,0,0,0);r.addView(down,a.lp(42,48));list.addView(r);a.gap(list,8);}};render[0].run();dialog(weather?"天气栏目显示与排序":"底部栏目显示与排序",c);
    }
}
